const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;
const research = Array.isArray(item.research) ? item.research : [];
const researchByCandidate = new Map(research.map((r) => [r.candidate, r]));

const ANALYTICS_WEIGHT = 0.6;
const FEASIBILITY_WEIGHT = 0.4;
const clamp = (value, min = 0, max = 100) => Math.max(min, Math.min(max, value));

const parseNumber = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value !== 'string') return null;
  const match = value.match(/(\d+(?:[.,]\d+)?)/);
  return match ? Number(match[1].replace(',', '.')) : null;
};
const parseContractDate = (value) => {
  if (typeof value !== 'string') return null;
  const match = value.match(/(\d{2})\.(\d{2})\.(\d{4})/);
  if (!match) return null;
  const date = new Date(Date.UTC(Number(match[3]), Number(match[2]) - 1, Number(match[1])));
  return Number.isNaN(date.getTime()) ? null : date;
};
const scoreMarketValue = (r) => {
  const million = (typeof r.marketValueMEUR === 'number' && Number.isFinite(r.marketValueMEUR)) ? r.marketValueMEUR : parseNumber(r.marketValue);
  if (million === null) return { score: null, detail: 'Marktwert nicht numerisch auswertbar.' };
  const score = clamp(100 - (1.5 * million));
  return { score, detail: `Marktwert ${million.toFixed(1)} Mio. EUR -> ${score.toFixed(1)}/100.` };
};
const scoreContract = (r) => {
  const value = r.contract;
  if (typeof value === 'string' && /(abl[oö]sefrei|vertragslos)/i.test(value)) return { score: 95, detail: 'Spieler ist abloesefrei/vertragslos -> 95/100.' };
  let date = null;
  if (typeof r.contractEndDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(r.contractEndDate)) {
    const parsed = new Date(`${r.contractEndDate}T00:00:00Z`);
    if (!Number.isNaN(parsed.getTime())) date = parsed;
  }
  if (!date) date = parseContractDate(value);
  if (date) {
    const months = (date.getTime() - Date.now()) / (1000 * 60 * 60 * 24 * 30.4375);
    let score;
    if (months <= 0) score = 100;
    else if (months <= 12) score = 90;
    else if (months <= 24) score = 70;
    else if (months <= 36) score = 50;
    else if (months <= 60) score = 30;
    else score = 15;
    return { score, detail: `Vertragsrestlaufzeit ca. ${Math.max(0, months).toFixed(1)} Monate -> ${score}/100.` };
  }
  if (typeof value === 'string' && /auslaufend/i.test(value)) return { score: 95, detail: 'Nur Freitext-Hinweis auf auslaufenden Vertrag, kein kanonisches Datum vorhanden -> 95/100.' };
  return { score: null, detail: 'Vertragsende nicht belastbar auswertbar.' };
};
const scoreInjuries = (value) => {
  if (typeof value !== 'string' || !value.trim()) return { score: null, detail: 'Verletzungshistorie nicht auswertbar.' };
  if (/(keine bekannten|keine verletzungen|verletzungsfrei)/i.test(value)) return { score: 90, detail: 'Keine bekannten relevanten Verletzungen -> 90/100.' };
  if (/(langzeit|wiederkehr|chronisch|schwer)/i.test(value)) return { score: 25, detail: 'Erhoehtes Verletzungsrisiko erkennbar -> 25/100.' };
  return { score: 55, detail: 'Verletzungslage ohne klaren Hochrisiko-Hinweis -> 55/100.' };
};
const scoreNews = (news) => {
  if (!Array.isArray(news) || news.length === 0) return { score: null, detail: 'Keine verwertbaren Transfer-News.' };
  const text = news.join(' ');
  if (/(unverk[aä]uflich|kein verkauf|not for sale|nicht abzugeben)/i.test(text)) return { score: 20, detail: 'News deuten auf geringe Verkaufsbereitschaft -> 20/100.' };
  if (/(wechselbereit|transferfreigabe|darf gehen|verkaufsbereit|wants to leave)/i.test(text)) return { score: 90, detail: 'News deuten auf hohe Transferbereitschaft -> 90/100.' };
  return { score: 60, detail: 'News ohne eindeutiges Transfersignal -> 60/100.' };
};
const scoreTransferLikelihood = (value) => {
  if (typeof value !== 'string' || !value.trim()) return { score: null, detail: 'Wechselwahrscheinlichkeit nicht belastbar beschrieben.' };
  if (/(lehnt.*verkauf|kein wechsel|unverk[aä]uflich|nicht abzugeben|bleibt sicher|unwahrscheinlich|keine wechselabsicht|not for sale)/i.test(value)) return { score: 15, detail: 'Explizite Hinweise sprechen gegen einen Transfer -> 15/100.' };
  if (/(wechselbereit|offen fuer.*wechsel|transferfreigabe|darf gehen|verkaufsbereit|wechsel wahrscheinlich|will wechseln|wants to leave)/i.test(value)) return { score: 90, detail: 'Explizite Hinweise sprechen fuer einen Transfer -> 90/100.' };
  return { score: 55, detail: 'Wechselhinweise sind vorhanden, aber nicht eindeutig -> 55/100.' };
};
const scoreCurrentSituation = (value) => {
  if (typeof value !== 'string' || !value.trim()) return { score: null, detail: 'Aktuelle sportliche Situation nicht auswertbar.' };
  if (/(ersatz|bank|wenig einsatz|kaum einsatz|keine rolle|unzufrieden|aussortiert|outside.*plans)/i.test(value)) return { score: 80, detail: 'Aktuelle Rolle kann einen Wechsel beguenstigen -> 80/100.' };
  if (/(stammspieler|schluesselspieler|unverzichtbar|kapitaen|key player)/i.test(value)) return { score: 30, detail: 'Aktuelle Schluesselrolle erschwert einen Wechsel -> 30/100.' };
  return { score: 55, detail: 'Aktuelle sportliche Situation ohne klares Verfuegbarkeitssignal -> 55/100.' };
};
const assessFeasibility = (r) => {
  if (!r || r.uncertain) return { known: false, score: null, components: {}, evidence: ['Keine belastbaren Due-Diligence-Fakten; Transfer-Realisierbarkeit bleibt unbekannt.'] };
  const components = {
    marketValue: scoreMarketValue(r), contract: scoreContract(r), injuries: scoreInjuries(r.injuries), news: scoreNews(r.news),
    transferLikelihood: scoreTransferLikelihood(r.transferLikelihoodNotes), currentSituation: scoreCurrentSituation(r.currentSituation)
  };
  const weighted = [['marketValue',0.25],['contract',0.25],['injuries',0.15],['news',0.10],['transferLikelihood',0.15],['currentSituation',0.10]]
    .filter(([key]) => typeof components[key].score === 'number');
  if (weighted.length < 3 || !weighted.some(([key]) => key === 'marketValue') || !weighted.some(([key]) => key === 'contract')) {
    return { known: false, score: null, components, evidence: Object.values(components).map((part) => part.detail) };
  }
  const totalWeight = weighted.reduce((sum, [, weight]) => sum + weight, 0);
  const score = weighted.reduce((sum, [key, weight]) => sum + (components[key].score * weight), 0) / totalWeight;
  return { known: true, score: clamp(score), components, evidence: Object.values(components).map((part) => part.detail) };
};

const evaluated = shortlist.map((candidate) => {
  const r = researchByCandidate.get(candidate.name) || null;
  const feasibility = assessFeasibility(r);
  const rankingFeasibility = feasibility.known ? feasibility.score : 50;
  const combinedScore = (ANALYTICS_WEIGHT * candidate.score) + (FEASIBILITY_WEIGHT * rankingFeasibility);
  return { candidate, research: r, feasibility, combinedScore, researchConfidence: (r && typeof r.confidence === 'number') ? r.confidence : null };
});
const ranked = [...evaluated].sort((a, b) => b.combinedScore !== a.combinedScore ? b.combinedScore - a.combinedScore : b.candidate.score - a.candidate.score);
const bestEntry = ranked[0];
const best = bestEntry.candidate;
const bestResearch = bestEntry.research;
const alternatives = ranked.slice(1).map((entry) => entry.candidate.name);
const uncertainties = ['Die Empfehlung basiert auf zum Recherchezeitpunkt extern verfuegbaren Web-Informationen; Aktualitaet und Vollstaendigkeit dieser externen Quellen sind nicht garantiert und sollten vor einer Entscheidung erneut geprueft werden.'];
if (item.playerRanking && item.playerRanking.positionApproximationApplied) uncertainties.push('Die angeforderte Position konnte im Kandidatenpool nur grob auf eine Positionsgruppe (DF/MF/FW/GK) angenaehert werden.');
if (!bestEntry.feasibility.known) uncertainties.push(`Fuer ${best.name} konnte aus den vorliegenden Due-Diligence-Fakten keine belastbare Transfer-Realisierbarkeit abgeleitet werden.`);
if (!bestResearch || bestResearch.uncertain) uncertainties.push(`Der Research-Zweig fuer ${best.name} ist unvollstaendig oder fehlgeschlagen.`);
else if (typeof bestResearch.confidence === 'number' && bestResearch.confidence < 0.5) uncertainties.push(`Die Recherche zu ${best.name} hat eine niedrige claim-basierte Konfidenz (${bestResearch.confidence}).`);
const risks = [];
if (bestResearch && !bestResearch.uncertain) risks.push(`Vertragslage: ${bestResearch.contract}. Marktwert: ${bestResearch.marketValue}. Verletzungshistorie: ${bestResearch.injuries}. Wechselhinweise: ${bestResearch.transferLikelihoodNotes || 'keine belastbaren Hinweise'}.`);
else risks.push(`Fuer ${best.name} liegt keine belastbare Due-Diligence-Recherche vor; Vertrags-, Marktwert-, Verletzungs- und Verfuegbarkeitsrisiken muessen vor einer Entscheidung real geprueft werden.`);
const reasoning = bestEntry.feasibility.known
  ? `${best.name} erreicht einen analytischen Fit von ${best.score} und eine aus Marktwert, Vertrag, Verletzungshistorie, News, Wechselwahrscheinlichkeit und aktueller sportlicher Situation abgeleitete Transfer-Realisierbarkeit von ${bestEntry.feasibility.score.toFixed(1)}/100. Kombinierter Score: ${bestEntry.combinedScore.toFixed(1)}.`
  : `${best.name} erzielt den hoechsten kombinierten Score (${bestEntry.combinedScore.toFixed(1)}), wobei die Transfer-Realisierbarkeit mangels belastbarer Fakten neutral mit 50 fuer die Sortierung behandelt und explizit als unbekannt markiert wurde.`;
const candidateEvaluations = ranked.map((entry) => ({
  candidate: entry.candidate.name, analyticsScore: entry.candidate.score,
  feasibilityScore: entry.feasibility.known ? Number(entry.feasibility.score.toFixed(2)) : null,
  feasibilityKnown: entry.feasibility.known, combinedScore: Number(entry.combinedScore.toFixed(2)), researchConfidence: entry.researchConfidence,
  feasibilityEvidence: entry.feasibility.evidence, researchEvidence: entry.research && Array.isArray(entry.research.evidence) ? entry.research.evidence : []
}));
const recommendation = {
  simulated: false, candidate: best.name, alternatives, reasoning, risks, uncertainties, candidateEvaluations,
  nextStep: 'Naechster Schritt: die Empfehlung inkl. Recherche-Ergebnisse in einem menschlichen Review vor der Kontaktaufnahme pruefen; der CSV-Analytics-Adapter bleibt bis zur Qlik-MCP-Anbindung ein temporaerer Ersatz.'
};
return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const lookup = item.playerProfileLookup;
const recommendation = { ...item.recommendation, candidateProfile: (lookup && lookup.found) ? lookup.profile : null };
return [{ json: { ...item, recommendation } }];

const item = $input.item.json;
const r = item.recommendation;
const errors = [];

if (!r || !r.candidate) errors.push('recommendation.candidate fehlt.');
if (!r || !Array.isArray(r.alternatives)) errors.push('recommendation.alternatives fehlt.');
if (!r || !r.reasoning) errors.push('recommendation.reasoning fehlt.');
if (!r || !Array.isArray(r.risks) || r.risks.length === 0) errors.push('recommendation.risks fehlt oder ist leer.');
if (!r || !Array.isArray(r.uncertainties) || r.uncertainties.length === 0) errors.push('recommendation.uncertainties fehlt oder ist leer.');
if (!r || !Array.isArray(r.candidateEvaluations) || r.candidateEvaluations.length === 0) errors.push('recommendation.candidateEvaluations fehlt oder ist leer.');
if (!r || !r.nextStep) errors.push('recommendation.nextStep fehlt.');

const valid = errors.length === 0;
return [{ json: { ...item, valid, errorMessage: valid ? undefined : 'Die Empfehlung ist technisch ungueltig.\n\n' + errors.join('\n') } }];

const item = $input.item.json;
if (item.valid === false) {
  throw new Error('[RECOMMENDATION] ' + (item.errorMessage || 'Empfehlung erstellen ist fehlgeschlagen.'));
}
return [{ json: { ...item, status: 'success' } }];
